import { isSupportedServerVersion } from '../services/runtimeVersion';
export { isNewerVersion } from '../services/runtimeVersion';
import { RIVET_VERSION } from '../config/telemetry';
import type { ServerHandshake } from './serverHandshake';

export type ServerVersionInfo = {
  cliVersion: string;
  serverVersion: string | null;
  staleServer: boolean;
};

export const serverVersionInfo = (
  handshake: Pick<ServerHandshake, 'rivetVersion'>,
): ServerVersionInfo => {
  const serverVersion = handshake.rivetVersion ?? null;
  return {
    cliVersion: RIVET_VERSION,
    serverVersion,
    staleServer: !isSupportedServerVersion(RIVET_VERSION, serverVersion),
  };
};

export const versionEnvelopeFields = (
  handshake: Pick<ServerHandshake, 'rivetVersion'>,
): Record<string, unknown> => {
  const info = serverVersionInfo(handshake);
  return {
    serverVersion: info.serverVersion,
    cliVersion: info.cliVersion,
    ...(info.staleServer
      ? {
          staleServer: true,
          upgradeHint:
            'The project server is running an older Rivet than this CLI. Run `rivet open` to restart it now. Interrupted work will need to be retried; saved directions remain available.',
        }
      : {}),
  };
};

export const staleWarningLine = (info: ServerVersionInfo): string =>
  `Project server is running rivet ${
    info.serverVersion ? `v${info.serverVersion}` : 'an unversioned build'
  } (this CLI is v${info.cliVersion}).`;
